"""Original explicit Chapter 3 answer contracts, keyed to supplied textbook artwork.
Run to write ../chapter-03.json. No shared bank is changed by this script.
"""
import gzip,json,hashlib,random,re,math
from pathlib import Path
import sympy as s
import numpy as np
ROOT=Path(__file__).resolve().parents[3]
SOURCE=json.loads(gzip.decompress((ROOT/'site/questions/calculus.json.gz').read_bytes()))
LIB=json.loads(gzip.decompress((ROOT/'site/questions/answer-library-calculus.json.gz').read_bytes()))['questions']
QS={q['id']:q for q in SOURCE if q['chapter']==3}; OUT={}; NOTES={}; TESTS=[]
def n(label,value,unit='',tol=1e-8):
 return dict(type='numeric',label=label,answer=float(value),tolerance=tol,unit=unit)
def c(label,answer,*wrong):
 if not wrong:
  if answer.count('=')==1 and not any(z in answer for z in ['≤','≥','≠']):
   lhs,rhs=answer.split('=');wrong=(lhs+'=−('+rhs+')',lhs+'=('+rhs+') + 1')
  else:wrong=('−('+answer+')','('+answer+') + 1')
 assert answer not in wrong and len(set(wrong))==len(wrong),(label,answer,wrong)
 return dict(type='choice',label=label,answer=answer,options=[answer,*wrong],selectionPrompt='Choose the correct '+label+'.')
def put(sec,num,fields,why='',limited=False,suffix=''):
 qid=f'calculus-section-3-{sec}-{num}'+suffix if isinstance(sec,int) else f'calculus-{sec}-{num}'+suffix
 assert qid in QS,qid
 assert qid not in OUT,qid
 if not isinstance(fields,list):fields=[fields]
 for i,f in enumerate(fields):
  f.update(provenance='explicit-source-inspected-original-answer-contract',explanation=why,hint='Use the source values, labeled quantities and stated domain. Check signs and units before choosing.')
  if f['type']=='choice':random.Random(hashlib.sha256((qid+'/'+str(i)).encode()).hexdigest()).shuffle(f['options'])
 scope='Checks the displayed quantities or selected mathematical conclusions. Freehand graphs, proofs, written interpretations and project reports are not automatically assessed.'
 grader={**fields[0],'scope':scope} if len(fields)==1 else dict(type='parts',parts=fields,scope=scope)
 if limited or re.search(r'\b(sketch|draw|prove|show|graph|interpret|explain)\b',QS[qid]['prompt'],re.I):grader['complete']=False
 OUT[qid]=dict(grader=grader,responsePartPrompt='Use the complete original textbook question above. Answer each labeled check below; graph and proof checks assess selected conclusions rather than the drawing or proof itself.',objectiveCheckVersion=2,objectiveChecksVerified=True,objectiveFieldCount=len(fields))
 NOTES[qid]=why

def row(sec,num,*fields,why='',limited=False):put(sec,num,list(fields),why,limited)
