def bisect(fn,a,b):
 fa=fn(a);fb=fn(b);assert fa*fb<0,(a,b,fa,fb)
 for _ in range(100):
  m=(a+b)/2;fm=fn(m)
  if fa*fm<=0:b=m
  else:a=m;fa=fm
 return(a+b)/2
